   [181]={next_id=182, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="如果这世上有地狱，想必也不过如此了。", msg_color="", msg_size=0, talker="白蔷薇", audio="", img="arts/ui/bg/story/cg/cg_ACT302_106.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [182]={next_id=183, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="一些士兵的身体颤抖了一下，仿佛被说中了心事，压抑的抽泣声更响了。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/cg/cg_ACT302_106.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [183]={next_id=184, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="但我希望你们也要记住，无论是天堂还是地狱，我在你们身边，克罗瓦德在你们身边！", msg_color="", msg_size=0, talker="白蔷薇", audio="", img="arts/ui/bg/story/cg/cg_ACT302_106.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
